// Labour Code 45/2019/QH14 art.98(1)(a): overtime on a normal working day is paid at least 150% of the normal hour.
// The roster's clocked overtime hours of each working or off day that is neither a weekly rest day nor a holiday.
const holiday = (d) => {
	const kind = get(d, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
const hours = sum(
	get(ctx, 'work.days', [])
		.filter((d) => !holiday(d) && ['WORK', 'OFF'].includes(get(d, 'day_type', '')))
		.map((d) => Number(get(d, 'overtime_hours', 0)))
);
return ctx.hour_rate * hours * ctx.lookup.multiplier;

// Labour Code 45/2019/QH14 art.98(1)(b); Decree 145/2020/NĐ-CP art.55(1)(b): every hour worked on a weekly rest day is overtime at
// least 200% of the normal hour; the employer's rest-day hourly multiple stands where it pays more.
const holiday = (d) => {
	const kind = get(d, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
const multiple = Math.max(
	ctx.lookup.rest_day_multiple,
	Number(get(ctx.subject.employer, 'pay_methods.rest_day_hourly_multiplier', 0))
);
const hours = sum(
	get(ctx, 'work.days', [])
		.filter((d) => get(d, 'day_type', '') === 'REST' && !holiday(d))
		.map((d) => Number(get(d, 'worked_hours', 0)))
);
return ctx.hour_rate * hours * multiple;

// Labour Code 45/2019/QH14 art.98(1)(c): every hour worked on a public holiday or paid day off is paid at least 300% of the
// normal hour, not counting the holiday pay a monthly wage already carries.
const holiday = (d) => {
	const kind = get(d, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
const hours = sum(get(ctx, 'work.days', []).filter(holiday).map((d) => Number(get(d, 'worked_hours', 0))));
return ctx.hour_rate * hours * ctx.lookup.multiplier;

// Labour Code 45/2019/QH14 arts.98(2), 106; Decree 145/2020/NĐ-CP art.56: every hour worked between 22:00 and 06:00, normal or
// overtime, earns at least 30% of the normal hour on top of its pay.
const zone = get(ctx.subject.employer, 'time_zone', 'Asia/Ho_Chi_Minh');
const night = (d) =>
	clock_window_minutes(get(d, 'intervals', []), zone, ctx.lookup.night_from, ctx.lookup.night_to, ctx.as_of) / 60;
return ctx.hour_rate * sum(get(ctx, 'work.days', []).map(night)) * ctx.lookup.multiplier;

// Labour Code 45/2019/QH14 art.98(3); Decree 145/2020/NĐ-CP art.57(1): a night overtime hour adds 20% of that day's daytime
// hour wage: 100% on a normal day with no daytime overtime, 150% where the day also has daytime overtime, 200% on a weekly rest
// day and 300% on a holiday. On a rest day or a holiday every hour is overtime; on other days only the clocked overtime spans.
const holiday = (d) => {
	const kind = get(d, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
const zone = get(ctx.subject.employer, 'time_zone', 'Asia/Ho_Chi_Minh');
const night = (d, field) =>
	clock_window_minutes(get(d, field, []), zone, ctx.lookup.night_from, ctx.lookup.night_to, ctx.as_of) / 60;
const rest = (d) => get(d, 'day_type', '') === 'REST';
const hours = (d) => (holiday(d) || rest(d) ? night(d, 'intervals') : night(d, 'overtime_intervals'));
const multiples = ctx.lookup.overtime_multiples;
const factor = (d) => {
	if (holiday(d)) return get(multiples, get(d, 'holiday_kind', ''), multiples.PUBLIC_HOLIDAY);
	if (rest(d)) return multiples.REST_DAY;
	return Number(get(d, 'overtime_hours', 0)) > hours(d) ? multiples.DAYTIME_OVERTIME : multiples.NORMAL_DAY;
};
return ctx.hour_rate * ctx.lookup.multiplier * sum(get(ctx, 'work.days', []).map((d) => hours(d) * factor(d)));
